CREATE OR REPLACE FUNCTION vexillology_contests.add_contest(p_name character varying, p_date character varying, p_prompt character varying, p_id character varying, p_year_end boolean, p_submission_start timestamp with time zone, p_submission_end timestamp with time zone, p_vote_start timestamp with time zone, p_vote_end timestamp with time zone, p_categories text[] DEFAULT NULL::text[])
 RETURNS void
 LANGUAGE plpgsql
AS $function$
DECLARE
    v_date DATE;
    v_category TEXT;
BEGIN
    -- VALIDATION: all scheduling defaults are now resolved by the caller
    -- (see server/contestSchedule.js), so every value here must be provided.
    IF p_name IS NULL OR TRIM(p_name) = '' THEN
        RAISE EXCEPTION 'p_name is required and cannot be empty';
    END IF;

    IF p_date IS NULL OR TRIM(p_date) = '' THEN
        RAISE EXCEPTION 'p_date is required and cannot be empty';
    END IF;

    IF p_prompt IS NULL OR TRIM(p_prompt) = '' THEN
        RAISE EXCEPTION 'p_prompt is required and cannot be empty';
    END IF;

    IF p_id IS NULL OR TRIM(p_id) = '' THEN
        RAISE EXCEPTION 'p_id is required and cannot be empty';
    END IF;

    IF p_submission_start IS NULL OR p_submission_end IS NULL
        OR p_vote_start IS NULL OR p_vote_end IS NULL THEN
        RAISE EXCEPTION 'submission/vote start and end timestamps are required';
    END IF;

    v_date := p_date::DATE;

    INSERT INTO vexillology_contests.contests (
        id,
        name,
        date,
        year_end,
        prompt,
        submission_start,
        submission_end,
        vote_start,
        vote_end
    )
    VALUES (
        p_id,
        p_name,
        v_date,
        coalesce(p_year_end, false),
        p_prompt,
        p_submission_start,
        p_submission_end,
        p_vote_start,
        p_vote_end
    );

    IF p_categories IS NOT NULL THEN
        FOREACH v_category IN ARRAY p_categories
        LOOP
            INSERT INTO vexillology_contests.contest_categories (
                contest_id,
                category
            )
            VALUES (
                p_id,
                v_category
            );
        END LOOP;
    END IF;
END;
$function$;

CREATE OR REPLACE FUNCTION vexillology_contests.backup_data(dest_schema text, p_truncate boolean DEFAULT false)
 RETURNS void
 LANGUAGE plpgsql
AS $function$
DECLARE
    v_source_schema TEXT := current_schema();
    v_tables_to_sync TEXT[] := ARRAY[
		'user_roles',
        'users',
        'background_colors',
		'contests',
		'contest_categories',
        'entries',
		'contest_entries',
		'votes'
    ];
    v_table_name TEXT;
    v_common_columns TEXT;
    v_pk_columns TEXT;
    v_update_clause TEXT;
    v_sql TEXT;

	v_mv_name TEXT;
BEGIN
    FOREACH v_table_name IN ARRAY v_tables_to_sync
    LOOP
        RAISE NOTICE 'Processing table: %', quote_ident(v_table_name);

        -- Step 1: Truncate if requested.
        IF p_truncate THEN
            v_sql := format('TRUNCATE TABLE %I.%I RESTART IDENTITY CASCADE', dest_schema, v_table_name);
            RAISE NOTICE 'Truncating destination table: %', v_sql;
            EXECUTE v_sql;
        END IF;

        -- Step 2: Find common columns.
        SELECT string_agg(quote_ident(c1.column_name), ', ')
        INTO v_common_columns
        FROM information_schema.columns AS c1
        WHERE c1.table_schema = v_source_schema AND c1.table_name = v_table_name
          AND EXISTS (
              SELECT 1 FROM information_schema.columns AS c2
              WHERE c2.table_schema = dest_schema AND c2.table_name = v_table_name AND c2.column_name = c1.column_name
          );

        IF v_common_columns IS NULL THEN
            RAISE NOTICE 'No common columns for table %. Skipping.', quote_ident(v_table_name);
            CONTINUE;
        END IF;

        -- Step 3: Find the primary key column(s).
        SELECT string_agg(quote_ident(kcu.column_name), ', ')
        INTO v_pk_columns
        FROM information_schema.table_constraints AS tc
        JOIN information_schema.key_column_usage AS kcu
          ON tc.constraint_name = kcu.constraint_name AND tc.table_schema = kcu.table_schema
        WHERE tc.constraint_type = 'PRIMARY KEY' AND tc.table_schema = dest_schema AND tc.table_name = v_table_name;

        -- Step 4: Build the INSERT statement conditionally.
        IF v_pk_columns IS NOT NULL THEN
            -- A primary key was found, so we might need to "upsert".
            SELECT string_agg(quote_ident(c.column_name) || ' = EXCLUDED.' || quote_ident(c.column_name), ', ')
            INTO v_update_clause
            FROM information_schema.columns c
            WHERE c.table_schema = dest_schema AND c.table_name = v_table_name
              AND c.column_name NOT IN (
                  SELECT kcu.column_name
                  FROM information_schema.table_constraints tc
                  JOIN information_schema.key_column_usage kcu
                    ON tc.constraint_name = kcu.constraint_name AND tc.table_schema = kcu.table_schema
                  WHERE tc.constraint_type = 'PRIMARY KEY' AND tc.table_schema = dest_schema AND tc.table_name = v_table_name
              );

            -- NEW: Check if there's anything to update.
            IF v_update_clause IS NOT NULL AND v_update_clause <> '' THEN
                -- Other columns exist, so DO UPDATE.
                v_sql := format(
                    'INSERT INTO %I.%I (%s) OVERRIDING SYSTEM VALUE SELECT %s FROM %I.%I ON CONFLICT (%s) DO UPDATE SET %s',
                    dest_schema, v_table_name,
                    v_common_columns,
                    v_common_columns,
                    v_source_schema, v_table_name,
                    v_pk_columns,
                    v_update_clause
                );
            ELSE
                -- No other columns to update (table is only a PK), so DO NOTHING.
                v_sql := format(
                    'INSERT INTO %I.%I (%s) OVERRIDING SYSTEM VALUE SELECT %s FROM %I.%I ON CONFLICT (%s) DO NOTHING',
                    dest_schema, v_table_name,
                    v_common_columns,
                    v_common_columns,
                    v_source_schema, v_table_name,
                    v_pk_columns
                );
            END IF;
        ELSE
            -- No primary key found, perform a simple INSERT.
            v_sql := format(
                'INSERT INTO %I.%I (%s) OVERRIDING SYSTEM VALUE SELECT %s FROM %I.%I',
                dest_schema, v_table_name,
                v_common_columns,
                v_common_columns,
                v_source_schema, v_table_name
            );
        END IF;

        -- Step 5: Execute the query.
        RAISE NOTICE 'Executing query: %', v_sql;
        EXECUTE v_sql;
    END LOOP;

    RAISE NOTICE 'Starting refresh of all materialized views in schema %...', quote_ident(dest_schema);

    -- Loop through all materialized views in the specified schema
    FOR v_mv_name IN
        SELECT
            c.relname
        FROM
            pg_class c
        JOIN
            pg_namespace n ON n.oid = c.relnamespace
        WHERE
            c.relkind = 'm' -- 'm' is for Materialized View
            AND n.nspname = dest_schema
    LOOP
        RAISE NOTICE 'Refreshing view: %', quote_ident(v_mv_name);
        BEGIN
            -- First, try to refresh concurrently to avoid locking
            EXECUTE format('REFRESH MATERIALIZED VIEW CONCURRENTLY %I.%I', dest_schema, v_mv_name);
        EXCEPTION
            WHEN OTHERS THEN
                -- If CONCURRENTLY fails (e.g., no unique index), fall back to a standard refresh
                RAISE WARNING 'Could not refresh %.% CONCURRENTLY. Falling back to standard REFRESH. Original error: %',
                    quote_ident(dest_schema), quote_ident(v_mv_name), SQLERRM;
                EXECUTE format('REFRESH MATERIALIZED VIEW %I.%I', dest_schema, v_mv_name);
        END;
    END LOOP;
END;
$function$;

