CREATE OR REPLACE FUNCTION vexillology_contests.create_best_of_year_contest(p_year integer DEFAULT NULL::integer)
 RETURNS void
 LANGUAGE plpgsql
AS $function$
DECLARE
    v_contest_id VARCHAR;
    v_contest_date DATE;
    v_contest_name VARCHAR;
    v_contest_prompt VARCHAR;
    v_sub_start TIMESTAMPTZ;
    v_sub_end TIMESTAMPTZ;
    v_vote_start TIMESTAMPTZ;
    v_vote_end TIMESTAMPTZ;
BEGIN
    -- 1. Default to current year if input is NULL
    IF p_year IS NULL THEN
        p_year := EXTRACT(YEAR FROM CURRENT_DATE)::INTEGER;
    END IF;

    -- 2. Construct IDs and Names based on the year
    -- Example: best24
    v_contest_id := 'best' || RIGHT(p_year::text, 2);
    -- Example: Best of 2024
    v_contest_name := 'Best of ' || p_year::text;
    -- add_contest requires a prompt. Markdown, shown on the contest page.
    -- Describes the best_of_year view's selection: update it if the view changes.
    v_contest_prompt := 'Vote for the best flag of ' || p_year::text || '. The entries are every '
        || 'contest''s top three finishers this year, plus the best entry from each of the year''s '
        || 'top 30 contestants.';

    -- 3. Define the Schedule
    -- Based on your example, the "Date" is Dec 23rd.
    v_contest_date := make_date(p_year, 12, 23);

    -- Submission Start: Nov 30th @ 9PM PST
    v_sub_start := (make_date(p_year, 11, 30) || ' 21:00:00')::TIMESTAMPTZ AT TIME ZONE 'America/Los_Angeles';

    -- Submission End: Dec 16th @ 9PM PST
    v_sub_end := (make_date(p_year, 12, 16) || ' 21:00:00')::TIMESTAMPTZ AT TIME ZONE 'America/Los_Angeles';

    -- Vote Start: Dec 23rd @ 9PM PST
    v_vote_start := (v_contest_date || ' 21:00:00')::TIMESTAMPTZ AT TIME ZONE 'America/Los_Angeles';

    -- Vote End: Dec 27th @ 9PM PST
    v_vote_end := (make_date(p_year, 12, 27) || ' 21:00:00')::TIMESTAMPTZ AT TIME ZONE 'America/Los_Angeles';

    -- 4. Call existing add_contest function
    PERFORM add_contest(
        p_name := v_contest_name,
        p_date := v_contest_date::VARCHAR,
        p_prompt := v_contest_prompt,
        p_id := v_contest_id,
        p_year_end := TRUE,
        p_submission_start := v_sub_start,
        p_submission_end := v_sub_end,
        p_vote_start := v_vote_start,
        p_vote_end := v_vote_end,
        p_categories := NULL
    );

    -- add_contest's body may still name a fixed schema. If the contest didn't land in this
    -- one, raise, which rolls back whatever add_contest wrote elsewhere.
    IF NOT EXISTS (SELECT 1 FROM contests WHERE id = v_contest_id) THEN
        RAISE EXCEPTION 'add_contest did not create contest % in schema %', v_contest_id, current_schema();
    END IF;

    -- 5. Populate contest_entries from the best_of_year view
    INSERT INTO contest_entries (contest_id, entry_id)
    SELECT
        v_contest_id,
        entry_id
    FROM
        best_of_year
    ON CONFLICT (contest_id, entry_id) DO NOTHING;

    RAISE NOTICE 'Contest % created for year % and populated with entries.', v_contest_id, p_year;

END;
$function$;

CREATE OR REPLACE FUNCTION vexillology_contests.has_user_permission(p_username character varying, p_permission character varying)
 RETURNS boolean
 LANGUAGE plpgsql
AS $function$
DECLARE
    v_role_id INTEGER;
    v_permission_granted BOOLEAN;
BEGIN
    -- Get the role_id for the given username
    SELECT role_id INTO v_role_id
    FROM users
    WHERE username = p_username;

    -- If the user has a role assigned, check the permission
    IF v_role_id IS NOT NULL THEN
        EXECUTE format('SELECT %I FROM user_roles WHERE id = %L', p_permission, v_role_id)
        INTO v_permission_granted;

        IF v_permission_granted IS TRUE THEN
            RETURN TRUE;
        ELSE
            RETURN FALSE;
        END IF;
    ELSE
        -- If the user has no role, return false
        RETURN FALSE;
    END IF;
END;
$function$;

CREATE OR REPLACE FUNCTION vexillology_contests.update_vote_timestamp()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
	begin
		NEW.last_modified = now();

return new;
end;

$function$;

-- Views

CREATE VIEW "vexillology_contests"."annual_standings" AS
SELECT rank() OVER (ORDER BY (sum(cs.average)) DESC) AS rank,
    e."user",
    round(sum(cs.average), 3) AS total,
    count(DISTINCT cs.contest_id) AS contests,
    count(*) AS flags,
    count(cs.rank) FILTER (WHERE cs.rank <= 20) AS "Top 20 Flags",
    count(cs.rank) FILTER (WHERE cs.rank = 1) AS "Winning Flags",
    round(avg(cs.average), 3) AS average,
    COALESCE(round(sum(cs.average) FILTER (WHERE to_char(c.date::timestamp with time zone, 'MM'::text) = '01'::text), 3), 0::numeric) AS jan,
    COALESCE(round(sum(cs.average) FILTER (WHERE to_char(c.date::timestamp with time zone, 'MM'::text) = '02'::text), 3), 0::numeric) AS feb,
    COALESCE(round(sum(cs.average) FILTER (WHERE to_char(c.date::timestamp with time zone, 'MM'::text) = '03'::text), 3), 0::numeric) AS mar,
    COALESCE(round(sum(cs.average) FILTER (WHERE to_char(c.date::timestamp with time zone, 'MM'::text) = '04'::text), 3), 0::numeric) AS apr,
    COALESCE(round(sum(cs.average) FILTER (WHERE to_char(c.date::timestamp with time zone, 'MM'::text) = '05'::text), 3), 0::numeric) AS may,
    COALESCE(round(sum(cs.average) FILTER (WHERE to_char(c.date::timestamp with time zone, 'MM'::text) = '06'::text), 3), 0::numeric) AS jun,
    COALESCE(round(sum(cs.average) FILTER (WHERE to_char(c.date::timestamp with time zone, 'MM'::text) = '07'::text), 3), 0::numeric) AS jul,
    COALESCE(round(sum(cs.average) FILTER (WHERE to_char(c.date::timestamp with time zone, 'MM'::text) = '08'::text), 3), 0::numeric) AS aug,
    COALESCE(round(sum(cs.average) FILTER (WHERE to_char(c.date::timestamp with time zone, 'MM'::text) = '09'::text), 3), 0::numeric) AS sep,
    COALESCE(round(sum(cs.average) FILTER (WHERE to_char(c.date::timestamp with time zone, 'MM'::text) = '10'::text), 3), 0::numeric) AS oct,
    COALESCE(round(sum(cs.average) FILTER (WHERE to_char(c.date::timestamp with time zone, 'MM'::text) = '11'::text), 3), 0::numeric) AS nov,
    COALESCE(round(sum(cs.average) FILTER (WHERE to_char(c.date::timestamp with time zone, 'MM'::text) = '12'::text), 3), 0::numeric) AS "dec"
   FROM vexillology_contests.contests_summary cs,
    vexillology_contests.entries e,
    vexillology_contests.contests c
  WHERE cs.entry_id::text = e.id::text AND cs.contest_id::text = c.id::text AND c.year_end = false AND to_char(c.date::timestamp with time zone, 'YYYY'::text) = to_char(now(), 'YYYY'::text) AND e.submission_status = 'approved'::vexillology_contests_common.submission_status
  GROUP BY e."user";

CREATE VIEW "vexillology_contests"."best_of_year" AS
SELECT sq."user",
    sq.contest_name,
    sq.entry_name,
    sq.entry_id,
    sq.average
   FROM ( SELECT e."user",
            c.name AS contest_name,
            e.name AS entry_name,
            cs.entry_id,
            round(cs.average, 3) AS average,
            row_number() OVER (PARTITION BY e."user" ORDER BY cs.average DESC) AS rank
           FROM vexillology_contests.entries e
             JOIN vexillology_contests.contest_entries ce ON e.id::text = ce.entry_id::text
             JOIN vexillology_contests.contests c ON ce.contest_id::text = c.id::text
             JOIN vexillology_contests.contests_summary cs ON e.id::text = cs.entry_id::text AND c.id::text = cs.contest_id::text
          WHERE to_char(c.date::timestamp with time zone, 'YYYY'::text) = to_char(now(), 'YYYY'::text) AND c.year_end = false AND (e."user"::text IN ( SELECT as2."user"
                   FROM vexillology_contests.annual_standings as2
                  ORDER BY as2.total DESC
                 LIMIT 30))) sq
  WHERE sq.rank = 1
UNION
 SELECT e."user",
    c.name AS contest_name,
    e.name AS entry_name,
    cs.entry_id,
    round(cs.average, 3) AS average
   FROM vexillology_contests.contests_summary cs,
    vexillology_contests.contests c,
    vexillology_contests.entries e
  WHERE cs.contest_id::text = c.id::text AND cs.entry_id::text = e.id::text AND c.year_end = false AND to_char(c.date::timestamp with time zone, 'YYYY'::text) = to_char(now(), 'YYYY'::text) AND cs.rank <= 3
  ORDER BY 5 DESC;

CREATE VIEW "vexillology_contests"."hall_of_fame" AS
SELECT c.name AS contest_name,
    c.date,
    l.contest_id,
    c.valid_reddit_id,
    c.winners_thread_id,
    l.entry_id,
    e."user",
    e.name AS entry_name,
    e.description,
    e.height,
    e.width,
    c.year_end,
    e.markdown,
    e.is_markdown
   FROM vexillology_contests.contests c,
    vexillology_contests.entries e,
    ( SELECT ce.contest_id,
            ce.entry_id
           FROM vexillology_contests.contest_entries ce
          WHERE ce.rank = 1
        UNION
         SELECT cs.contest_id,
            cs.entry_id
           FROM vexillology_contests.contests_summary cs,
            vexillology_contests.contests c_1
          WHERE cs.contest_id::text = c_1.id::text AND c_1.local_voting = true AND c_1.vote_end < now() AND cs.rank = 1) l
  WHERE c.id::text = l.contest_id::text AND e.id::text = l.entry_id::text
  ORDER BY c.date DESC;

-- Indexes

CREATE INDEX contest_entries_contest_id_idx ON vexillology_contests.contest_entries USING btree (contest_id);

CREATE INDEX contest_entries_entry_id_idx ON vexillology_contests.contest_entries USING btree (entry_id);

CREATE INDEX contest_entries_position_idx ON vexillology_contests.contest_entries USING btree (rank);

CREATE INDEX votes_contest_id_idx ON vexillology_contests.votes USING btree (contest_id);

-- Triggers

CREATE TRIGGER update_last_modified BEFORE UPDATE ON vexillology_contests.votes FOR EACH ROW EXECUTE FUNCTION vexillology_contests.update_vote_timestamp();
